"use client";

import { memo, useState, type ComponentProps } from "react";
import * as motion from "motion/react-client";
import { useReducedMotion } from "motion/react";
import { cn } from "cn";
import { Canvas } from "./canvas";
import shader from "./pastel-mascot-background.wgsl";

export type MeshGradientBackgroundProps = ComponentProps<"div"> & {
  speed?: number;
  intensity?: number;
  interactive?: boolean;
};

export const MeshGradientBackground = memo(function MeshGradientBackground({
  className,
  children,
  speed = 1,
  intensity = 1,
  interactive = true,
  onPointerMove,
  onPointerLeave,
  ...props
}: MeshGradientBackgroundProps = {}) {
  const reducedMotion = useReducedMotion();
  const [pointer, setPointer] = useState({ x: 0.5, y: 0.5, active: 0 });
  const rate = Number.isFinite(speed) ? Math.max(0, speed) : 1;
  const brightness = Number.isFinite(intensity) ? Math.max(0, Math.min(2, intensity)) : 1;

  return (
    <div
      {...props}
      data-slot="mesh-gradient-background"
      className={cn(
        "relative isolate min-h-96 overflow-hidden border border-border bg-background",
        className,
      )}
      onPointerMove={(event) => {
        onPointerMove?.(event);
        if (!interactive || reducedMotion || event.pointerType === "touch") return;
        const bounds = event.currentTarget.getBoundingClientRect();
        setPointer({
          x: (event.clientX - bounds.left) / bounds.width,
          y: (event.clientY - bounds.top) / bounds.height,
          active: 1,
        });
      }}
      onPointerLeave={(event) => {
        onPointerLeave?.(event);
        setPointer({ x: 0.5, y: 0.5, active: 0 });
      }}
    >
      <Canvas
        aria-label="Animated pastel mesh gradient"
        role="img"
        shader={shader}
        label="mesh-gradient-background"
        lightFallback="radial-gradient(ellipse at 28% 25%, #ffd4e5, transparent 44%), radial-gradient(ellipse at 72% 30%, #b8e5f7, transparent 48%), linear-gradient(135deg, #d4e5f0, #f5edf9)"
        fallback="radial-gradient(ellipse at 28% 25%, #ffb3d9, transparent 44%), radial-gradient(ellipse at 72% 30%, #87ceeb, transparent 48%), radial-gradient(ellipse at 55% 75%, #4a90e2, transparent 58%), radial-gradient(ellipse at 20% 72%, #2c3e50, #1a1a2e 72%)"
        fallbackContent={
          <motion.div
            aria-hidden="true"
            className="absolute inset-[-18%]"
            style={{
              backgroundImage:
                "radial-gradient(ellipse at 28% 25%, #ffb3d9 0%, transparent 44%), radial-gradient(ellipse at 72% 30%, #87ceeb 0%, transparent 48%), radial-gradient(ellipse at 55% 75%, #4a90e2 0%, transparent 58%), radial-gradient(ellipse at 20% 72%, #2c3e50 0%, #1a1a2e 72%)",
              backgroundSize: "140% 140%",
            }}
            animate={
              reducedMotion
                ? undefined
                : {
                    x: ["-6%", "6%", "-6%"],
                    y: ["-4%", "5%", "-4%"],
                    scale: [1, 1.08, 1],
                  }
            }
            transition={
              reducedMotion ? undefined : { duration: 5, repeat: Infinity, ease: "easeInOut" }
            }
          />
        }
        className="absolute inset-0 -z-10 h-full min-h-0 border-0 bg-transparent"
        animated={rate > 0}
        fps={30}
        uniforms={(time, size) => ({
          cfg: {
            metrics: [size[0], size[1], time * rate, brightness],
            pointer: [pointer.x, pointer.y, interactive && !reducedMotion ? pointer.active : 0, 0],
          },
        })}
      />
      {children}
    </div>
  );
});

import { lightBlue, lightCyan, lightPaper, lightRose, lightSurface, lightViolet } from "./light-palette.shared.wgsl";

struct Theme { mode: vec4f };
@group(1) @binding(0) var<uniform> theme: Theme;

struct Config {
  metrics: vec4f, // width, height, time, intensity
  pointer: vec4f, // normalized position, hover amount
};
@group(0) @binding(0) var<uniform> cfg: Config;

const PI: f32 = 3.14159265359;

fn hash21(p: vec2f) -> f32 {
  var p3 = fract(vec3f(p.x, p.y, p.x) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

fn valueNoise(st: vec2f) -> f32 {
  let i = floor(st);
  let f = fract(st);
  let u = f * f * (3.0 - 2.0 * f);
  let a = hash21(i);
  let b = hash21(i + vec2f(1.0, 0.0));
  let c = hash21(i + vec2f(0.0, 1.0));
  let d = hash21(i + vec2f(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

fn rotate(p: vec2f, angle: f32) -> vec2f {
  let c = cos(angle);
  let s = sin(angle);
  return vec2f(p.x * c - p.y * s, p.x * s + p.y * c);
}

fn getPosition(index: f32, time: f32) -> vec2f {
  let a = index * 0.37;
  let b = 0.6 + fract(index / 3.0) * 0.9;
  let c = 0.8 + fract((index + 1.0) / 4.0);
  return 0.5 + 0.5 * vec2f(sin(time * b + a), cos(time * c + a * 1.5));
}

@fragment fn fs_main(@location(0) uvInput: vec2f) -> @location(0) vec4f {
  var uv = uvInput;
  let time = 0.5 * (cfg.metrics.z + 41.5);
  let distortion = 0.8;
  let swirl = 0.1;
  let radius = smoothstep(0.0, 1.0, length(uv - 0.5));
  let center = 1.0 - radius;

  for (var i = 1.0; i <= 2.0; i += 1.0) {
    uv.x += distortion * center / i *
      sin(time + i * 0.4 * smoothstep(0.0, 1.0, uv.y)) *
      cos(0.2 * time + i * 2.4 * smoothstep(0.0, 1.0, uv.y));
    uv.y += distortion * center / i *
      cos(time + i * 2.0 * smoothstep(0.0, 1.0, uv.x));
  }

  let uvRotated = rotate(uv - 0.5, -3.0 * swirl * radius) + 0.5;
  let pointer = (cfg.pointer.xy - 0.5) * cfg.pointer.z * 0.04;
  let sampleUv = uvRotated + pointer;

  let colors = array<vec3f, 5>(
    vec3f(1.0, 0.702, 0.851),
    vec3f(0.529, 0.808, 0.922),
    vec3f(0.290, 0.565, 0.886),
    vec3f(0.169, 0.243, 0.314),
    vec3f(0.102, 0.102, 0.181)
  );

  let lightColors = array<vec3f, 5>(mix(lightRose(), lightPaper(), 0.5), mix(lightCyan(), lightPaper(), 0.45), mix(lightBlue(), lightPaper(), 0.35), mix(lightViolet(), lightPaper(), 0.45), lightSurface());
  var color = vec3f(0.0);
  var totalWeight = 0.0;
  for (var index = 0.0; index < 5.0; index += 1.0) {
    let position = getPosition(index, time);
    let distance = pow(length(sampleUv - position), 3.5);
    let weight = 1.0 / (distance + 0.001);
    color += select(colors[u32(index)], lightColors[u32(index)], theme.mode.x > 0.5) * weight;
    totalWeight += weight;
  }

  color /= max(totalWeight, 0.0001);
  return vec4f(color * cfg.metrics.w, 1.0);
}

"use client";

import { memo, useEffect, useRef, type ReactNode, type ComponentProps } from "react";
import { useReducedMotion } from "motion/react";
import { createShaderRenderer, type PostProcessOptions } from "./shader-renderer.shared";
import { cn } from "cn";

type RendererOptions = Parameters<typeof createShaderRenderer>[2];
export interface CanvasProps extends ComponentProps<"div"> {
  shader: Parameters<typeof createShaderRenderer>[1];
  label?: string;
  fallback: string;
  lightFallback: string;
  fallbackContent?: ReactNode;
  uniforms: RendererOptions["uniforms"];
  animated?: boolean;
  fps?: number;
  dpr?: number | [number, number];
  postProcess?: PostProcessOptions;
}

/** Shared rendering only; consumers own uniforms and pointer behavior. */
export const Canvas = memo(function Canvas({
  shader,
  label = "shader-canvas",
  fallback,
  lightFallback,
  fallbackContent,
  uniforms,
  animated = true,
  fps = 30,
  dpr = 1,
  postProcess,
  className,
  children,
  ...props
}: CanvasProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const latestUniforms = useRef(uniforms);
  const rendererRef = useRef<ReturnType<typeof createShaderRenderer> | null>(null);
  const reducedMotion = useReducedMotion();
  const minDpr = typeof dpr === "number" ? dpr : dpr[0];
  const maxDpr = typeof dpr === "number" ? dpr : dpr[1];
  useEffect(() => {
    latestUniforms.current = uniforms;
    rendererRef.current?.render();
  }, [uniforms]);
  useEffect(() => {
    if (!canvasRef.current) return;
    const renderer = createShaderRenderer(canvasRef.current, shader, {
      label,
      uniforms: (time, size) => latestUniforms.current(time, size),
      animated: animated && !reducedMotion,
      fps,
      surface: { dpr: minDpr === maxDpr ? minDpr : [minDpr, maxDpr] },
      postProcess,
    });
    rendererRef.current = renderer;
    return () => {
      renderer.dispose();
      rendererRef.current = null;
    };
  }, [shader, label, animated, reducedMotion, fps, minDpr, maxDpr, postProcess]);
  return (
    <div
      {...props}
      data-slot={label}
      className={cn(
        "hangry-background relative isolate min-h-96 overflow-hidden border border-border bg-background",
        className,
      )}
    >
      <div aria-hidden="true" className="pointer-events-none absolute inset-0 -z-10">
        <div className="absolute inset-0 dark:hidden" style={{ backgroundImage: lightFallback }} />
        <div className="absolute inset-0 hidden dark:block">
          <div className="absolute inset-0" style={{ backgroundImage: fallback }} />
          {fallbackContent}
        </div>
        <canvas ref={canvasRef} className="absolute inset-0 block h-full w-full opacity-0" />
      </div>
      {children}
    </div>
  );
});

import {
  effect,
  frame,
  frameLoop,
  init,
  sampler,
  surface,
  target,
  type Frame,
  type SurfaceOptions,
} from "vgpu";

type ShaderSource = Parameters<typeof effect>[1];
type Bindings = Parameters<ReturnType<typeof effect>["set"]>[0];

export interface PostProcessOptions {
  label: string;
  source: ShaderSource;
  uniforms?: (time: number, size: readonly [number, number]) => Bindings;
}

interface ShaderRendererOptions {
  label: string;
  uniforms: (time: number, size: readonly [number, number]) => Bindings;
  animated?: boolean;
  fps?: number;
  surface?: SurfaceOptions;
  postProcess?: PostProcessOptions;
  themeAware?: boolean;
  themeMask?: boolean;
}

/** Owns one canvas effect. Components supply bindings and retain their own input/UI logic. */
export function createShaderRenderer(
  canvas: HTMLCanvasElement,
  source: ShaderSource,
  {
    label,
    uniforms,
    animated = true,
    fps = 60,
    surface: surfaceOptions = { dpr: 1 },
    postProcess,
    themeAware = true,
    themeMask = false,
  }: ShaderRendererOptions,
) {
  let disposed = false;
  let gpu: Awaited<ReturnType<typeof init>> | undefined;
  let output: ReturnType<typeof surface> | undefined;
  let scene: ReturnType<typeof target> | undefined;
  let themeObserver: MutationObserver | undefined;
  let light = themeAware && !document.documentElement.classList.contains("dark");
  const theme = () => ({ mode: [Number(light), Number(themeMask), 0, 0] });
  let sceneSampler: ReturnType<typeof sampler> | undefined;
  let shader: ReturnType<typeof effect> | undefined;
  let postShader: ReturnType<typeof effect> | undefined;
  let loop: ReturnType<typeof frameLoop> | undefined;
  let observer: ResizeObserver | undefined;
  let unsubscribeResize: (() => void) | undefined;
  let pendingFrame = 0;
  let draw: ((currentFrame: Frame) => void) | undefined;
  canvas.style.opacity = "0";

  const dispose = () => {
    if (disposed) return;
    disposed = true;
    loop?.stop();
    observer?.disconnect();
    themeObserver?.disconnect();
    cancelAnimationFrame(pendingFrame);
    unsubscribeResize?.();
    shader?.dispose();
    postShader?.dispose();
    output?.dispose();
    gpu?.dispose();
  };
  const render = () => {
    if (disposed || !draw || animated) return;
    cancelAnimationFrame(pendingFrame);
    pendingFrame = requestAnimationFrame(() => {
      if (!disposed && gpu && draw) frame(gpu, draw);
    });
  };
  const start = async () => {
    const initialized = await init();
    if (disposed) {
      initialized.dispose();
      return;
    }
    gpu = initialized;
    output = surface(gpu, canvas, surfaceOptions);
    scene = postProcess ? target(gpu, { size: output.size }) : undefined;
    sceneSampler = postProcess
      ? sampler(gpu, { minFilter: "linear", magFilter: "linear" })
      : undefined;
    light = themeAware && !document.documentElement.classList.contains("dark");
    shader = effect(gpu, source, {
      label,
      set: { ...uniforms(0, (scene ?? output).size), theme: theme() },
    });
    postShader = postProcess
      ? effect(gpu, postProcess.source, {
          label: postProcess.label,
          set: {
            theme: theme(),
            scene: scene,
            sceneSampler,
            ...postProcess.uniforms?.(0, output.size),
          },
        })
      : undefined;
    await shader.compile(scene ?? output);
    await postShader?.compile(output);
    if (disposed) return;
    const startedAt = performance.now();
    if (output && scene && sceneSampler) {
      unsubscribeResize = output.onResize(({ width, height }) => {
        scene?.resize([width, height]);
        postShader?.set({
          scene,
          sceneSampler,
          ...postProcess?.uniforms?.(0, [width, height]),
        });
      });
    }
    draw = (currentFrame) => {
      if (!output || !shader || disposed) return;
      const time = animated ? (performance.now() - startedAt) / 1000 : 0;
      const renderTarget = scene ?? output;
      shader.set({ ...uniforms(time, renderTarget.size), theme: theme() });
      if (postShader && scene && sceneSampler) {
        postShader.set({
          theme: theme(),
          scene,
          sceneSampler,
          ...postProcess?.uniforms?.(time, output.size),
        });
        currentFrame.pass(scene, shader);
        currentFrame.pass(output, postShader);
      } else {
        currentFrame.pass(scene ?? output, shader);
      }
      canvas.style.opacity = "1";
    };
    if (themeAware) {
      themeObserver = new MutationObserver(() => {
        light = themeAware && !document.documentElement.classList.contains("dark");
        render();
      });
      themeObserver.observe(document.documentElement, {
        attributes: true,
        attributeFilter: ["class"],
      });
    }
    if (animated) loop = frameLoop(gpu, draw, { fps });
    else {
      observer = new ResizeObserver(render);
      observer.observe(canvas);
      render();
    }
  };
  void start().catch((error: unknown) => {
    if (!disposed) {
      canvas.style.opacity = "0";
      console.warn(`${label} could not start; retaining its fallback:`, error);
      dispose();
    }
  });
  return { dispose, render };
}

// Dedicated pigments for light-mode shader materials. No output filtering.
export fn lightPaper() -> vec3f { return vec3f(0.9568627, 0.9803922, 0.9647059); }
export fn lightSurface() -> vec3f { return vec3f(0.8470588, 0.9333333, 0.8862745); }
export fn lightInk() -> vec3f { return vec3f(0.0666667, 0.2352941, 0.1960784); }
export fn lightEmerald() -> vec3f { return vec3f(0.0000000, 0.4862745, 0.3450980); }
export fn lightCyan() -> vec3f { return vec3f(0.0000000, 0.5450980, 0.7215686); }
export fn lightBlue() -> vec3f { return vec3f(0.1568627, 0.3686275, 0.9098039); }
export fn lightViolet() -> vec3f { return vec3f(0.5098039, 0.2666667, 0.8470588); }
export fn lightRose() -> vec3f { return vec3f(0.8392157, 0.2352941, 0.5137255); }
export fn lightGold() -> vec3f { return vec3f(0.8431373, 0.5764706, 0.1137255); }
